window.AUTH=window.AUTH||{};window.AUTH["24-5438"]={"d":"24-5438","id":"2025/24-5438","n":"Bowe v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Michael Bowe","date":"2025-04-07","url":"https://www.supremecourt.gov/DocketPDF/24/24-5438/354841/20250407132513522_Bowe%20Merits%20Brief%20FINAL.pdf","side":"pet","n":59},{"k":"respondent","label":"Brief of respondent United States","date":"2025-06-11","url":"https://www.supremecourt.gov/DocketPDF/24/24-5438/362867/20250611130453359_24-5438bsUnitedStates.pdf","side":"res","n":100},{"k":"reply","label":"Reply of petitioner Michael Bowe","date":"2025-09-22","url":"https://www.supremecourt.gov/DocketPDF/24/24-5438/375436/20250922105855721_Bowe%20Reply%20FINAL.pdf","side":"pet","n":25}],"opinion":"https://www.supremecourt.gov/opinions/25pdf/607us1r04_n7ip.pdf","tr":true,"items":[{"t":"case","label":"Avery v. United States","cite":"140 S. Ct. 1080","y":2020,"url":"https://www.courtlistener.com/c/S.%20Ct./140/1080/","sc":1,"by":{"0":"9","1":"41"},"q":[{"src":"argument","who":"Mr. Yang","text":"As you may remember, Justice Kavanaugh, you wrote separately in a case called Avery. Avery came out of the Sixth Circuit raising this exact (b)(1) issue, but it came in a different posture."},{"src":"argument","who":"Mr. Yang","text":"There's no limit -- this is kind of like an Avery issue. It came up on the merits because it had been resolved by the court of appeals. And the court of appeals said, yeah -- you know, this Court said, no, no, no, this is not the grant or denial of a second or successive."}]},{"t":"case","label":"Bowe v. United States, __ S. Ct. __","cite":"2025 WL 226843","y":2025,"court":"Jan. 17","by":{"0":"11"},"q":[{"src":"brief","b":0,"text":"cause a newsworthy event and stir up the bloggers and podcasters by asking the [Supreme] Court to accept a certified question from a court of appeals for only the fifth time in 78 years.","cite":"2025 WL 226843"}]},{"t":"case","label":"Bowen v. Mich. Academy of Family Physicians","cite":"476 U.S. 667","y":1986,"id":"1985/85-225","sc":1,"by":{"0":"42"}},{"t":"case","label":"Brown v. United States","cite":"942 F.3d 1069","y":2019,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/942/1069/","by":{"0":"7"}},{"t":"case","label":"Burt v. Titlow","cite":"571 U.S. 12","y":2013,"id":"2013/12-414","sc":1,"by":{"0":"25–26"},"q":[{"src":"brief","b":0,"text":"AEDPA recognizes a foundational principle of our federal system: State courts are adequate forums for the vindication of federal rights.","cite":"571 U.S. 12, 19"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"recognizes a foundational principle of our federal system: State courts are adequate forums for the vindication of federal rights.","cite":"571 U. S. 12, 19"}]},{"t":"case","label":"Castro v. United States","cite":"540 U.S. 375","y":2003,"id":"2003/02-6683","sc":1,"by":{"0":"28, 36, 38, 40–41, 43, 33","2":"15, 17–18, 21–23"},"q":[{"src":"brief","b":0,"text":"read[s] limitations on [its] jurisdiction to review narrowly.","cite":"540 U.S. 375, 381"},{"src":"brief","b":0,"text":"had the effect of denying ‘authorization . . . to file’","cite":"540 U.S. at 380"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"diffcult to reconcile with the basic principle that we `read limitations on our jurisdiction to review narrowly.'","cite":"540 U. S., at 381"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"close our doors to a class of habeas petitioners.","cite":"540 U. S., at 381"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"close our doors to a class of habeas petitioners seeking review.","cite":"540 U. S., at 381"},{"src":"argument","who":"Mr. Adler","text":"This argument is based on Castro and the passage on page 380 that starts with the sentence \"Even if for argument's sake.\" The Court assumed that there was a denial of an authorization because the court of appeals had stated that the prisoner could not satisfy the gatekeeping requirements."},{"src":"argument","who":"Justice Sotomayor","text":"Because of the Castro argument?"},{"src":"argument","who":"Mr. Adler","text":"Of course, our position is that the Court does not need to address this argument because we have three other narrower arguments. And this, of course, was the same approach that this Court took in Castro, where it --"}]},{"t":"case","label":"Chamber of Commerce of U.S. v. Whiting","cite":"563 U.S. 582","y":2011,"id":"2010/09-115","sc":1,"by":{"0":"23"}},{"t":"case","label":"Cheney v. U.S. Dist. Ct. for the Dist. of Columbia","cite":"542 U.S. 367","y":2004,"id":"2003/03-475","sc":1,"by":{"0":"47"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"by":{"0":"43","1":"31, 39, 40"},"q":[{"src":"brief","b":0,"text":"rest[s] on the reasonable presumption that Congress did not intend the alternative [construction] which raises serious constitutional doubts.","cite":"543 U.S. 371, 381"}]},{"t":"case","label":"Connecticut Nat’l Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"by":{"0":"17"},"q":[{"src":"brief","b":0,"text":"stated time and again that courts must presume that a legislature says in a statute what it means and means in a statute what it says there.","cite":"503 U.S. 249, 253–54"},{"src":"brief","b":0,"text":"When the words of a statute are unambiguous, then, this first canon is also the last: judicial inquiry is complete.","cite":"503 U.S. at 254"}]},{"t":"case","label":"Dodd v. United States","cite":"545 U.S. 353","y":2005,"id":"2004/04-5286","sc":1,"by":{"0":"19, 25"}},{"t":"case","label":"Duncan v. Walker","cite":"533 U.S. 167","y":2001,"id":"2000/00-121","sc":1,"by":{"0":"26"},"q":[{"src":"brief","b":0,"text":"The exhaustion requirement of § 2254(b) ensures that state courts have the opportunity fully to consider federal-law challenges to a state custodial judgment before the lower federal courts may entertain a collateral attack upon that judgment.","cite":"533 U.S. 167, 178–79"}]},{"t":"case","label":"Felker v. Turpin","cite":"518 U.S. 651","y":1996,"id":"1995/95-8836","sc":1,"by":{"0":"10, 29, 45–46","1":"8, 19, 22, 23, 25, 40, 41"},"q":[{"src":"brief","b":1,"text":"creates a ‘gatekeeping’ mechanism for the consideration of second or successive applications in district court.","cite":"518 U.S. 651, 657"},{"src":"opinion","who":"Justice Jackson, concurring","text":"mak[e] no mention of our authority,","cite":"518 U. S., at 661"},{"src":"argument","who":"Mr. Adler","text":"It is Felker versus Turpin, which is a habeas case that says no implied repeals of habeas jurisdiction, the Court applies it here to (b)(3)(E)."}]},{"t":"case","label":"Gonzalez v. Crosby","cite":"545 U.S. 524","y":2005,"id":"2004/04-6432","sc":1,"by":{"0":"5"}},{"t":"case","label":"Green v. United States","cite":"397 F.3d 101","y":2005,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/397/101/","by":{"0":"20"}},{"t":"case","label":"Groff v. DeJoy","cite":"600 U.S. 447","y":2023,"id":"2022/22-174","sc":1,"by":{"0":"21"}},{"t":"case","label":"Gustafson v. Alloyd Co., Inc.","cite":"513 U.S. 561","y":1995,"id":"1994/93-404","sc":1,"by":{"0":"22"},"q":[{"src":"brief","b":0,"text":"the normal rule of statutory construction [is] that identical words used in different parts of the same act are intended to have the same meaning.","cite":"513 U.S. 561, 570"}]},{"t":"case","label":"Harrington v. Richter","cite":"562 U.S. 86","y":2011,"id":"2010/09-587","sc":1,"by":{"0":"26"},"q":[{"src":"brief","b":0,"text":"[f]ederal habeas review of state convictions frustrates both the States’ sovereign power to punish offenders and their good-faith attempts to honor constitutional rights.","cite":"562 U.S. 86, 103"}]},{"t":"case","label":"Hohn v. United States","cite":"524 U.S. 236","y":1998,"id":"1997/96-8986","sc":1,"by":{"0":"29–30","1":"33, 34"},"q":[{"src":"brief","b":0,"text":"state prisoners filing second or successive habeas applications under § 2254.","cite":"524 U.S. 236, 249"},{"src":"brief","b":0,"text":"with the absence of an analogous limitation to certiorari review","cite":"524 U.S. at 250"},{"src":"argument","who":"Mr. Adler","text":"And we pointed this out in our initial brief with the Hohn decision, and that case drew a contrast between (b)(3)(E) as a clear statement and a certificate of appealability provision in 2253, which didn't have that."}]},{"t":"case","label":"INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"by":{"0":"28, 31–32, 43–44","1":"32"},"q":[{"src":"brief","b":0,"text":"the longstanding rule requiring a clear statement of congressional intent to repeal habeas jurisdiction.","cite":"533 U.S. 289, 298"},{"src":"brief","b":0,"text":"if an otherwise acceptable construction of a statute would raise serious constitutional problems, and where an alternative interpretation of the statute is fairly possible, we are obligated to construe the statute to avoid such problems.","cite":"533 U.S. at 299"},{"src":"brief","b":1,"text":"the longstanding rule requiring a clear statement of congressional intent to repeal habeas jurisdiction,","cite":"533 U.S. 289, 298"}]},{"t":"case","label":"Int’l Union, United Auto., Aerospace & Agr. Implement Workers of Am. v. Brock","cite":"477 U.S. 274","y":1986,"id":"1985/84-1777","sc":1,"by":{"0":"42"}},{"t":"case","label":"Jimenez v. Quarterman","cite":"555 U.S. 113","y":2009,"id":"2008/07-6984","sc":1,"by":{"0":"16"},"q":[{"src":"brief","b":0,"text":"As with any question of statutory interpretation, our analysis begins with the plain language of the statute.","cite":"555 U.S. 113, 118"}]},{"t":"case","label":"Johnson v. United States","cite":"576 U.S. 591","y":2015,"id":"2014/13-7120","sc":1,"by":{"0":"6","1":"6, 11"}},{"t":"case","label":"Jones v. Hendrix","cite":"599 U.S. 465","y":2023,"id":"2022/21-857","sc":1,"by":{"0":"4, 17–19, 21, 30, 46","1":"1, 3, 7, 8, 14, 22, 25, 42, 49","2":"9, 11"},"q":[{"src":"brief","b":0,"text":"attribut[e] to Congress an intention to render a statute so internally inconsistent.","cite":"599 U.S. at 479"},{"src":"brief","b":1,"text":"Congress has chosen finality over error correction,","cite":"599 U.S. at 480"},{"src":"brief","b":1,"text":"barred unless they rely on either ‘newly discovered evidence,’ * * * or ‘a new rule of constitutional law.’","cite":"599 U.S. 465, 469"},{"src":"brief","b":2,"text":"Here, as often is the case, the best interpretation is the straightforward one.","cite":"599 U.S. 465, 480"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"two—and only two—condi- Page Proof Pending Publication tions in which a second or successive § 2255 motion may proceed.","cite":"599 U. S., at 477"},{"src":"argument","who":"Mr. Adler","text":"Hendrix, there is really no viable way for this Court to be able to ensure the uniformity of federal law here. Now the amicus beef -- brief by the federal courts professors lays this out very well and summarizes the scholarship, but this case is a unique one in the sense that original habeas has always functioned as a safety valve here."},{"src":"argument","who":"Mr. Adler","text":"Hendrix, then this particular split, I think, highlights the potential constitutional problem in a way that no other split would. Now other splits could still raise the question because this Court has rarely, if ever, actually used its original habeas power, but this particular split, I think, is -- is the problem here because there's really no other viable way for this Court to resolve this circuit conflict on (b)(1)."}]},{"t":"case","label":"Jones v. United States","cite":"36 F.4th 974","y":2022,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/36/974/","by":{"0":"22"},"q":[{"src":"brief","b":0,"text":"no reason to credit the cross-reference to § 2254 in § 2244(b)(2) but ignore it in § 2244(b)(1).","cite":"36 F.4th 974, 983"}]},{"t":"case","label":"Lamie v. U.S. Trustee","cite":"540 U.S. 526","y":2004,"id":"2003/02-693","sc":1,"by":{"0":"17"},"q":[{"src":"brief","b":0,"text":"It is well established that when the statute’s language is plain, the sole function of the courts . . . is to enforce it according to its terms.","cite":"540 U.S. 526, 534"}]},{"t":"case","label":"Magwood v. Patterson","cite":"561 U.S. 320","y":2010,"id":"2009/09-158","sc":1,"by":{"0":"17","1":"36, 44, 45"},"q":[{"src":"brief","b":1,"text":"requirement of custody pursuant to a state-court judgment distinguishes [Section] 2254 from other statutory provisions authorizing relief from constitutional violations—such as [Section] 2255, which allows challenges to the judgments of federal courts.","cite":"561 U.S. at 333"}]},{"t":"case","label":"Martinez-Villareal v. Stewart","cite":"118 F.3d 628","y":1997,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/118/628/","by":{"0":"37"}},{"t":"case","label":"McNary v. Haitian Refugee Ctr., Inc.","cite":"498 U.S. 479","y":1991,"id":"1990/89-1332","sc":1,"by":{"0":"42"}},{"t":"case","label":"McQuiggin v. Perkins","cite":"569 U.S. 383","y":2013,"id":"2012/12-126","sc":1,"by":{"0":"27"}},{"t":"case","label":"Nat’l Ass’n of Mfrs. v. Dep’t of Defense","cite":"583 U.S. 109","y":2018,"url":"https://supreme.justia.com/cases/federal/us/583/109/","sc":1,"by":{"0":"19","2":"4"},"q":[{"src":"brief","b":0,"text":"is unambiguous, [the] inquiry begins with the statutory text, and ends there as well.","cite":"583 U.S. 109, 127"}]},{"t":"case","label":"Niz-Chavez v. Garland","cite":"593 U.S. 155","y":2021,"id":"2020/19-863","sc":1,"by":{"0":"19"},"q":[{"src":"brief","b":0,"text":"sole function is to apply the law as [they] find it.","cite":"593 U.S. 155, 160"}]},{"t":"case","label":"Neil v. Biggers","cite":"409 U.S. 188","y":1972,"id":"1972/71-586","sc":1,"by":{"0":"24"},"q":[{"src":"brief","b":0,"text":"embodies a recognition that if this Court has ‘actually adjudicated’ a claim on direct appeal or certiorari, a state prisoner has had the federal redetermination to which he is entitled. A subsequent application for habeas corpus raising the same claims would serve no valid purpose and would add unnecessarily to an already overburdened system of criminal justice.","cite":"409 U.S. 188, 191"}]},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"by":{"0":"30","1":"27, 36, 46"},"q":[{"src":"brief","b":0,"text":"principle of statutory construction that when Congress includes particular language in one section of a statute but omits it in another section of the same Act, it is generally presumed that Congress acts intentionally and purposefully.","cite":"464 U.S. 16, 23"},{"src":"brief","b":1,"text":"[w]here Congress includes particular language in one section of a statute but omits it in another section of the same Act, it is gen- erally presumed that Congress acts intentionally and purposely in the disparate inclusion or exclusion.","cite":"464 U.S. 16, 23"},{"src":"argument","who":"Mr. Yang","text":"And the -- no one has -- has come up with any explanation that -- that will respond to the Russello presumption. It's a strong presumption."}]},{"t":"case","label":"Rust v. Sullivan","cite":"500 U.S. 173","y":1991,"id":"1990/89-1391","sc":1,"by":{"0":"43"},"q":[{"src":"brief","b":0,"text":"legislates in the light of constitutional limitations.","cite":"500 U.S. at 191"}]},{"t":"case","label":"Santos-Zacaria v. Garland","cite":"598 U.S. 411","y":2023,"id":"2022/21-1436","sc":1,"by":{"0":"21"}},{"t":"case","label":"Shinn v. Ramirez","cite":"596 U.S. 366","y":2022,"id":"2021/20-1009","sc":1,"by":{"0":"26"}},{"t":"case","label":"Shoop v. Twyford","cite":"596 U.S. 811","y":2022,"id":"2021/21-511","sc":1,"by":{"0":"25–26"},"q":[{"src":"brief","b":0,"text":"to advance the principles of comity, finality, and federalism.","cite":"596 U.S. 811, 818"},{"src":"brief","b":0,"text":"ensur[ing] that the state trial on the merits is the main event, so to speak, rather than a tryout on the road for what will later be the determinative federal habeas hearing.","cite":"596 U.S. at 819"}]},{"t":"case","label":"Stewart v. Martinez-Villareal","cite":"523 U.S. 637","y":1998,"id":"1997/97-300","sc":1,"by":{"0":"37–38, 40–41","1":"37, 38","2":"17–18, 20, 22"},"q":[{"src":"brief","b":2,"text":"what the Court of Appeals did.","cite":"523 U.S. at 641"}]},{"t":"case","label":"Taylor v. Gilkey","cite":"314 F.3d 832","y":2002,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/314/832/","by":{"0":"20"}},{"t":"case","label":"Thompson v. Calderon","cite":"151 F.3d 918","y":1998,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/151/918/","by":{"0":"34"}},{"t":"case","label":"Triestman v. United States","cite":"124 F.3d 361","y":1997,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/124/361/","by":{"0":"34","1":"25, 27"}},{"t":"case","label":"United States v. Cotton","cite":"535 U.S. 625","y":2002,"id":"2001/01-687","sc":1,"by":{"0":"34"},"q":[{"src":"brief","b":0,"text":"court’s power to hear a case . . . can never be forfeited or waived","cite":"535 U.S. 625, 630"}]},{"t":"case","label":"United States v. Davis","cite":"588 U.S. 445","y":2019,"id":"2018/18-431","sc":1,"by":{"0":"7–8, 10–11, 43","1":"6, 12, 41","2":"12–14, 16"}},{"t":"case","label":"United States v. Seale","cite":"558 U.S. 985","y":2009,"url":"https://supreme.justia.com/cases/federal/us/558/985/","sc":1,"by":{"0":"47"}},{"t":"case","label":"United States v. Taylor","cite":"596 U.S. 845","y":2022,"id":"2021/20-1459","sc":1,"by":{"0":"7–8, 27","1":"6, 13, 42","2":"12–14"}},{"t":"case","label":"United States, ex rel. Polanksy v. Exec. Health Res., Inc.","cite":"599 U.S. 419","y":2023,"id":"2022/21-1052","sc":1,"by":{"0":"21","2":"9"}},{"t":"case","label":"Utah v. Evans","cite":"536 U.S. 452","y":2002,"id":"2001/01-714","sc":1,"by":{"0":"28"},"q":[{"src":"argument","who":"Mr. Yang","text":"Well, if you look at what Castro cites, it cites to, for the clear statement, Utah versus Evans."},{"src":"argument","who":"Mr. Yang","text":"Yeah. I'm -- I'm trying to pivot back to -- to what Utah versus Evans --"},{"src":"argument","who":"Mr. Yang","text":"Same question, though, about whether it's second or successive, whether that's barred. Then you look at Utah, Utah versus Evans, which is ultimately the cite for the narrow reading."}]},{"t":"case","label":"Will v. United States","cite":"389 U.S. 90","y":1967,"id":"1967/36","sc":1,"by":{"0":"47"},"q":[{"src":"brief","b":0,"text":"Mandamus, of course, may never be employed as a substitute for appeal.","cite":"389 U.S. 90, 97"},{"src":"brief","b":0,"text":"only exceptional circumstances amounting to a judicial usurpation of power,","cite":"389 U.S. at 95"}]},{"t":"case","label":"Williams v. United States","cite":"927 F.3d 427","y":2019,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/927/427/","by":{"0":"20"}},{"t":"case","label":"Wisniewski v. United States","cite":"353 U.S. 901","y":1957,"url":"https://supreme.justia.com/cases/federal/us/353/901/","sc":1,"by":{"0":"47","1":"32"}},{"t":"case","label":"Woods v. Donald","cite":"575 U.S. 312","y":2015,"id":"2014/14-618","sc":1,"by":{"0":"26"},"q":[{"src":"brief","b":0,"text":"reflect a presumption that state courts know and follow the law.","cite":"575 U.S. 312, 316"}]},{"t":"const","label":"Article I, Section 8, Clause 9","text":"To constitute Tribunals inferior to the supreme Court;","by":{"0":"45"}},{"t":"const","label":"Article III, Section 1","clauses":[["judicial-vesting","Judicial Vesting Clause"]],"text":"The judicial Power of the United States, shall be vested in one supreme Court, and in such inferior Courts as the Congress may from time to time ordain and establish. The Judges, both of the supreme and inferior Courts, shall hold their Offices during good Behaviour, and shall, at stated Times, receive for their Services, a Compensation, which shall not be diminished during their Continuance in Office.","by":{"0":"45"}},{"t":"const","label":"Article III, Section 2","clauses":[["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"]],"text":"The judicial Power shall extend to all Cases, in Law and Equity, arising under this Constitution, the Laws of the United States, and Treaties made, or which shall be made, under their Authority;—to all Cases affecting Ambassadors, other public Ministers and Consuls;—to all Cases of admiralty and maritime Jurisdiction;—to Controversies to which the United States shall be a Party;—to Controversies between two or more States;— between a State and Citizens of another State,—between Citizens of different States,—between Citizens of the same State claiming Lands under Grants of different States, and between a State, or the Citizens thereof, and foreign States, Citizens or Subjects. In all Cases affecting Ambassadors, other public Ministers and Consuls, and those in which a State shall be Party, the supreme Court shall have original Jurisdiction. In all the other Cases before mentioned, the supreme Court shall have appellate Jurisdiction, both as to Law and Fact, with such Exceptions, and under such Regulations as the Congress shall make. The Trial of all Crimes, except in Cases of Impeachment, shall be by Jury; and such Trial shall be held in the State where the said Crimes shall have been committed; but when not committed within any State, the Trial shall be at such Place or Places as the Congress may by Law have directed.","by":{"0":"44"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(c)","(e)","(e)(2)(B)(ii)","(c)(2006)","(c)(3)(A)","(c)(3)(B)"],"stext":{"head":"§924. Penalties","paras":[[0,"(a)(1) Except as otherwise provided in this subsection, subsection (b), (c), (f), or (p) of this section, or in section 929, whoever—"],[1,"(A) knowingly makes any false statement or representation with respect to the information required by this chapter to be kept in the records of a person licensed under this chapter or in applying for any license or exemption or relief from disability under the provisions of this chapter;"],[1,"(B) knowingly violates subsection (a)(4), (f), (k), or (q) of section 922;"],[1,"(C) knowingly imports or brings into the United States or any possession thereof any firearm or ammunition in violation of section 922(l); or"],[1,"(D) willfully violates any other provision of this chapter,"],[0,"shall be fined under this title, imprisoned not more than five years, or both."],[0,"(2) Whoever knowingly violates subsection (a)(6), (h), (i), (j), or (o) of section 922 shall be fined as provided in this title, imprisoned not more than 10 years, or both."],[0,"(3) Any licensed dealer, licensed importer, licensed manufacturer, or licensed collector who knowingly—"],[1,"(A) makes any false statement or representation with respect to the information required by the provisions of this chapter to be kept in the records of a person licensed under this chapter, or"],[1,"(B) violates subsection (m) of section 922,"],[0,"shall be fined under this title, imprisoned not more than one year, or both."],[0,"(4) Whoever violates section 922(q) shall be fined under this title, imprisoned for not more than 5 years, or both. Notwithstanding any other provision of law, the term of imprisonment imposed under this paragraph shall not run concurrently with any other term of imprisonment imposed under any other provision of law. Except for the authorization of a term of imprisonment of not more than 5 years made in this paragraph, for the purpose of any other law a violation of section 922(q) shall be deemed to be a misdemeanor."],[0,"(5) Whoever knowingly violates subsection (s) or (t) of section 922 shall be fined under this title, imprisoned for not more than 1 year, or both."],[0,"(6)(A)(i) A juvenile who violates section 922(x) shall be fined under this title, imprisoned not more than 1 year, or both, except that a juvenile described in clause (ii) shall be sentenced to probation on appropriate conditions and shall not be incarcerated unless the juvenile fails to comply with a condition of probation."],[0,"(ii) A juvenile is described in this clause if—"],[1,"(I) the offense of which the juvenile is charged is possession of a handgun or ammunition in violation of section 922(x)(2); and"],[1,"(II) the juvenile has not been convicted in any court of an offense (including an offense under section 922(x) or a similar State law, but not including any other offense consisting of conduct that if engaged in by an adult would not constitute an offense) or adjudicated as a juvenile delinquent for conduct that if engaged in by an adult would constitute an offense."],[0,"(B) A person other than a juvenile who knowingly violates section 922(x)—"],[1,"(i) shall be fined under this title, imprisoned not more than 1 year, or both; and"],[1,"(ii) if the person sold, delivered, or otherwise transferred a handgun or ammunition to a juvenile knowing or having reasonable cause to know that the juvenile intended to carry or otherwise possess or discharge or otherwise use the handgun or ammunition in the commission of a crime of violence, shall be fined under this title, imprisoned not more than 10 years, or both."],[0,"(7) Whoever knowingly violates section 931 shall be fined under this title, imprisoned not more than 3 years, or both."],[0,"(8) Whoever knowingly violates subsection (d) or (g) of section 922 shall be fined under this title, imprisoned for not more than 15 years, or both."],[0,"(b) Whoever, with intent to commit therewith an offense punishable by imprisonment for a term exceeding one year, or with knowledge or reasonable cause to believe that an offense punishable by imprisonment for a term exceeding one year is to be committed therewith, ships, transports, or receives a firearm or any ammunition in interstate or foreign commerce shall be fined under this title, or imprisoned not more than ten years, or both."],[0,"(c)(1)(A) Except to the extent that a greater minimum sentence is otherwise provided by this subsection or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries a firearm, or who, in furtherance of any such crime, possesses a firearm, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime—"],[1,"(i) be sentenced to a term of imprisonment of not less than 5 years;"],[1,"(ii) if the firearm is brandished, be sentenced to a term of imprisonment of not less than 7 years; and"],[1,"(iii) if the firearm is discharged, be sentenced to a term of imprisonment of not less than 10 years."],[0,"(B) If the firearm possessed by a person convicted of a violation of this subsection—"],[1,"(i) is a short-barreled rifle, short-barreled shotgun, or semiautomatic assault weapon, the person shall be sentenced to a term of imprisonment of not less than 10 years; or"],[1,"(ii) is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, the person shall be sentenced to a term of imprisonment of not less than 30 years."],[0,"(C) In the case of a violation of this subsection that occurs after a prior conviction under this subsection has become final, the person shall—"],[1,"(i) be sentenced to a term of imprisonment of not less than 25 years; and"],[1,"(ii) if the firearm involved is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, be sentenced to imprisonment for life."],[0,"(D) Notwithstanding any other provision of law—"],[1,"(i) a court shall not place on probation any person convicted of a violation of this subsection; and"],[1,"(ii) no term of imprisonment imposed on a person under this subsection shall run concurrently with any other term of imprisonment imposed on the person, including any term of imprisonment imposed for the crime of violence or drug trafficking crime during which the firearm was used, carried, or possessed."],[0,"(2) For purposes of this subsection, the term \"drug trafficking crime\" means any felony punishable under the Controlled Substances Act (21 U.S.C. 801 et seq.), the Controlled Substances Import and Export Act (21 U.S.C. 951 et seq.), or chapter 705 of title 46."],[0,"(3) For purposes of this subsection the term \"crime of violence\" means an offense that is a felony and—"],[1,"(A) has as an element the use, attempted use, or threatened use of physical force against the person or property of another, or"],[1,"(B) that by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense."],[0,"(4) For purposes of this subsection, the term \"brandish\" means, with respect to a firearm, to display all or part of the firearm, or otherwise make the presence of the firearm known to another person, in order to intimidate that person, regardless of whether the firearm is directly visible to that person."],[0,"(5) Except to the extent that a greater minimum sentence is otherwise provided under this subsection, or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries armor piercing ammunition, or who, in furtherance of any such crime, possesses armor piercing ammunition, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime or conviction under this section—"],[1,"(A) be sentenced to a term of imprisonment of not less than 15 years; and"],[1,"(B) if death results from the use of such ammunition—"],[2,"(i) if the killing is murder (as defined in section 1111), be punished by death or sentenced to a term of imprisonment for any term of years or for life; and"],[2,"(ii) if the killing is manslaughter (as defined in section 1112), be punished as provided in section 1112."],[0,"(d)(1) Any firearm or ammunition involved in or used in any knowing violation of subsection (a)(4), (a)(6), (f), (g), (h), (i), (j), or (k) of section 922, or knowing importation or bringing into the United States or any possession thereof any firearm or ammunition in violation of section 922(l), or knowing violation of section 924, 932, or 933, or willful violation of any other provision of this chapter or any rule or regulation promulgated thereunder, or any violation of any other criminal law of the United States, or any firearm or ammunition intended to be used in any offense referred to in paragraph (3) of this subsection, where such intent is demonstrated by clear and convincing evidence, shall be subject to seizure and forfeiture, and all provisions of the Internal Revenue Code of 1986 relating to the seizure, forfeiture, and disposition of firearms, as defined in section 5845(a) of that Code, shall, so far as applicable, extend to seizures and forfeitures under the provisions of this chapter: Provided, That upon acquittal of the owner or possessor, or dismissal of the charges against him other than upon motion of the Government prior to trial, or lapse of or court termination of the restraining order to which he is subject, the seized or relinquished firearms or ammunition shall be returned forthwith to the owner or possessor or to a person delegated by the owner or possessor unless the return of the firearms or ammunition would place the owner or possessor or his delegate in violation of law. Any action or proceeding for the forfeiture of firearms or ammunition shall be commenced within one hundred and twenty days of such seizure."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/924?type=usc&year=mostrecent&link-type=html"},"by":{"0":"6–7","1":"11, 12, 6, 11, 20, 6, 11, 12, 20, 42, 12, 13, 42, 12, 41","2":"13"},"q":[{"src":"brief","b":1,"text":"has as an element the use, attempted use, or threatened use of physical force against the person or property of another,","cite":"18 U.S.C. 924(c)(3)(A)"}]},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)","(2)"],"stext":{"head":"§1254. Courts of appeals; certiorari; certified questions","paras":[[0,"Cases in the courts of appeals may be reviewed by the Supreme Court by the following methods:"],[1,"(1) By writ of certiorari granted upon the petition of any party to any civil or criminal case, before or after rendition of judgment or decree;"],[1,"(2) By certification at any time by a court of appeals of any question of law in any civil or criminal case as to which instructions are desired, and upon such certification the Supreme Court may give binding instructions or require the entire record to be sent up for decision of the entire matter in controversy."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1254?type=usc&year=mostrecent&link-type=html"},"by":{"0":"1","1":"41"}},{"t":"law","label":"Pub. L. No. 104-132","url":"https://www.govinfo.gov/link/plaw/104/public/132","by":{"0":"2","1":"1"}},{"t":"case","label":"Abbott v. Perez","cite":"585 U.S. 579","y":2018,"id":"2017/17-586","sc":1,"by":{"1":"36","2":"19"},"q":[{"src":"argument","who":"Mr. Yang","text":"Appellate -- mandatory appellate jurisdiction under 1253 and what was formerly 1254(2), and if you look at, like, Abbott versus Perez or Maine versus Taylor, the Court narrowly construes those grants of -- grants of jurisdiction, and it does not sit comfortably to narrowly construe exceptions to jurisdiction in light of those precedents."}]},{"t":"case","label":"Abuelhawa v. United States","cite":"556 U.S. 816","y":2009,"id":"2008/08-192","sc":1,"by":{"1":"49"}},{"t":"case","label":"Artuz v. Bennett","cite":"531 U.S. 4","y":2000,"id":"2000/99-1238","sc":1,"by":{"1":"36"}},{"t":"case","label":"Banister v. Davis","cite":"590 U.S. 504","y":2020,"id":"2019/18-6943","sc":1,"by":{"1":"49"}},{"t":"case","label":"Bennett v. United States","cite":"119 F.3d 468","y":1997,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/119/468/","by":{"1":"37"}},{"t":"case","label":"Bessent v. Dellinger","cite":"145 S. Ct. 1326","y":2025,"url":"https://www.courtlistener.com/c/S.%20Ct./145/1326/","sc":1,"by":{"1":"35"}},{"t":"case","label":"Biden v. Nebraska","cite":"600 U.S. 477","y":2023,"id":"2022/22-506","sc":1,"by":{"1":"35"}},{"t":"case","label":"Blackledge v. Allison","cite":"431 U.S. 63","y":1977,"id":"1976/75-1693","sc":1,"by":{"1":"29"}},{"t":"case","label":"Bondi v. VanDerStok","cite":"145 S. Ct. 857","y":2025,"id":"2024/23-852","sc":1,"by":{"1":"39"}},{"t":"case","label":"Burton v. Stewart","cite":"549 U.S. 147","y":2007,"id":"2006/05-9222","sc":1,"by":{"1":"25, 32"}},{"t":"case","label":"Cooper v. Woodford","cite":"358 F.3d 1117","y":2004,"url":"https://www.courtlistener.com/c/F.3d/358/1117/","by":{"1":"29"}},{"t":"case","label":"Corley v. United States","cite":"556 U.S. 303","y":2009,"id":"2008/07-10441","sc":1,"by":{"1":"24"}},{"t":"case","label":"Dawkins v. United States","cite":"829 F.3d 549","y":2016,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/829/549/","by":{"1":"37"}},{"t":"case","label":"Duncan v. Bonta","cite":"131 F.4th 1019","y":2025,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/131/1019/","by":{"1":"29"}},{"t":"case","label":"Gallagher v. United States","cite":"711 F.3d 315","y":2013,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/711/315/","by":{"1":"37"}},{"t":"case","label":"Gonzalez v. Automatic Emps. Credit Union","cite":"419 U.S. 90","y":1974,"id":"1974/73-858","sc":1,"by":{"1":"18, 35, 36, 38","2":"19"},"q":[{"src":"brief","b":1,"text":"dismissal of a complaint on grounds short of the merits does ‘deny’ the injunction in a literal sense.","cite":"419 U.S. 90, 96"},{"src":"brief","b":1,"text":"frequently deviated from the path of literalism,","cite":"419 U.S. at 96"}]},{"t":"case","label":"Ikome v. Bondi","cite":"2025 WL 1573183","y":2025,"court":"June 4","by":{"1":"35"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"583 U.S. 281","y":2018,"id":"2017/15-1204","sc":1,"by":{"1":"39"},"q":[{"src":"brief","b":1,"text":"‘a serious doubt’ is raised about the constitutionality of an Act of Congress,","cite":"583 U.S. at 296"}]},{"t":"case","label":"Mayle v. Felix","cite":"545 U.S. 644","y":2005,"id":"2004/04-563","sc":1,"by":{"1":"1, 8","2":"6"},"q":[{"src":"brief","b":1,"text":"to advance the finality of criminal convictions.","cite":"545 U.S. 644, 662"},{"src":"opinion","who":"Justice Jackson, concurring","text":"to advance the fnality of criminal convictions.","cite":"545 U. S. 644, 662"},{"src":"opinion","who":"Justice Jackson, concurring","text":"advance the fnality of criminal convictions,","cite":"545 U. S., at 662"}]},{"t":"case","label":"McCleskey v. Zant","cite":"499 U.S. 467","y":1991,"id":"1990/89-7024","sc":1,"by":{"1":"40, 48","2":"11"},"q":[{"src":"brief","b":1,"text":"[A]t common law[,] an order denying habeas relief could not be reviewed","cite":"499 U.S. 467, 479"},{"src":"brief","b":1,"text":"qualified application of the doctrine of res judicata,","cite":"499 U.S. at 486"},{"src":"brief","b":2,"text":"[f]inality has special importance in the context of a federal attack on a state conviction.","cite":"499 U.S. 467, 491"}]},{"t":"case","label":"Melendez v. United States","cite":"518 U.S. 120","y":1996,"id":"1995/95-5661","sc":1,"by":{"1":"24"}},{"t":"case","label":"Págan-San Miguel v. United States","cite":"736 F.3d 44","y":2013,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/736/44/","by":{"1":"25"}},{"t":"case","label":"Rhines v. Weber","cite":"544 U.S. 269","y":2005,"id":"2004/03-9046","sc":1,"by":{"1":"29, 30"},"q":[{"src":"brief","b":1,"text":"purposes is to ‘reduce delays in the execution of state and federal criminal sentences.’","cite":"544 U.S. 269, 276"},{"src":"brief","b":1,"text":"might deliberately engage in dilatory tactics to * * * avoid execution of the sentence of death.","cite":"544 U.S. at 277"}]},{"t":"case","label":"Salinger v. Loisel","cite":"265 U.S. 224","y":1924,"id":"scdb/1923-152","sc":1,"by":{"1":"49"}},{"t":"case","label":"Sanders v. United States","cite":"373 U.S. 1","y":1963,"id":"1962/202","sc":1,"by":{"1":"48, 49","2":"14"},"q":[{"src":"brief","b":1,"text":"den[y the claim] without [a] hearing.","cite":"373 U.S. at 8"}]},{"t":"case","label":"Summerlin v. Stewart","cite":"309 F.3d 1193","y":2002,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/309/1193/","by":{"1":"29"}},{"t":"case","label":"United States v. Addonizio","cite":"442 U.S. 178","y":1979,"id":"1978/78-156","sc":1,"by":{"1":"7"},"q":[{"src":"brief","b":1,"text":"the more convenient jurisdiction of the sentencing court,","cite":"442 U.S. 178, 185"}]},{"t":"case","label":"United States v. Campbell","cite":"26 F.4th 860","y":2022,"url":"https://www.courtlistener.com/c/F.4th/26/860/","by":{"1":"29"}},{"t":"case","label":"United States v. Handy","cite":"646 Fed. Appx. 635","y":2016,"court":"10th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./646/635/","by":{"1":"37"}},{"t":"case","label":"United States v. Hayman","cite":"342 U.S. 205","y":1952,"id":"scdb/1951-024","sc":1,"by":{"1":"7"}},{"t":"case","label":"United States v. Lorentsen","cite":"106 F.3d 278","y":1997,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/106/278/","by":{"1":"25"}},{"t":"case","label":"United States v. St. Hubert","cite":"909 F.3d 335","y":2018,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/909/335/","by":{"1":"13"}},{"t":"case","label":"Welch v. United States","cite":"578 U.S. 120","y":2016,"id":"2015/15-6418","sc":1,"by":{"1":"11"},"q":[{"src":"argument","who":"Ms. Mitchell","text":"But Judge Rosenbaum in the Eleventh Circuit observed that in the three months after this Court's decision in Welch, the Eleventh Circuit saw 1800 applications for Johnson-based review."}]},{"t":"case","label":"White v. United States","cite":"371 F.3d 900","y":2004,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/371/900/","by":{"1":"37"}},{"t":"case","label":"Williams v. Taylor","cite":"529 U.S. 420","y":2000,"id":"1999/99-6615","sc":1,"by":{"1":"49"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"to further the principles of comity, fnality, and federalism.","cite":"529 U. S. 420, 436"}]},{"t":"case","label":"Woodford v. Garceau","cite":"538 U.S. 202","y":2003,"id":"2002/01-1862","sc":1,"by":{"1":"8"}},{"t":"const","label":"Article III, Section 2, Clause 2","clauses":[["original-jurisdiction","Original and Appellate Jurisdiction"]],"text":"In all Cases affecting Ambassadors, other public Ministers and Consuls, and those in which a State shall be Party, the supreme Court shall have original Jurisdiction. In all the other Cases before mentioned, the supreme Court shall have appellate Jurisdiction, both as to Law and Fact, with such Exceptions, and under such Regulations as the Congress shall make.","by":{"1":"19, 39-41"}},{"t":"usc","label":"28 U.S.C. § 1651","url":"https://www.law.cornell.edu/uscode/text/28/1651","by":{"1":"19"}},{"t":"usc","label":"18 U.S.C. § 1951","url":"https://www.law.cornell.edu/uscode/text/18/1951","subs":["(a)"],"by":{"1":"6, 11, 6, 11"}},{"t":"usc","label":"28 U.S.C. § 46","url":"https://www.law.cornell.edu/uscode/text/28/46","subs":["(c)"],"by":{"1":"28"}},{"t":"usc","label":"28 U.S.C. § 1253","url":"https://www.law.cornell.edu/uscode/text/28/1253","stext":{"head":"§1253. Direct appeals from decisions of three-judge courts","paras":[[0,"Except as otherwise provided by law, any party may appeal to the Supreme Court from an order granting or denying, after notice and hearing, an interlocutory or permanent injunction in any civil action, suit or proceeding required by any Act of Congress to be heard and determined by a district court of three judges."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1253?type=usc&year=mostrecent&link-type=html"},"by":{"1":"35, 36","2":"18–19"}},{"t":"usc","label":"28 U.S.C. § 2241","url":"https://www.law.cornell.edu/uscode/text/28/2241","by":{"1":"9"}},{"t":"usc","label":"28 U.S.C. § 2244","url":"https://www.law.cornell.edu/uscode/text/28/2244","subs":["(a)","(b)","(b)(1)","(b)(2)","(b)(2)(A)","(b)(2)(B)","(b)(2)(B)(ii)","(b)(3)","(b)(3)(A)","(b)(3)(B)","(b)(3)(C)","(b)(3)(D)","(b)(3)(E)","(b)(4)","(c)","(d)","(d)(1)"],"stext":{"head":"§2244. Finality of determination","paras":[[0,"(a) No circuit or district judge shall be required to entertain an application for a writ of habeas corpus to inquire into the detention of a person pursuant to a judgment of a court of the United States if it appears that the legality of such detention has been determined by a judge or court of the United States on a prior application for a writ of habeas corpus, except as provided in section 2255."],[0,"(b)(1) A claim presented in a second or successive habeas corpus application under section 2254 that was presented in a prior application shall be dismissed."],[0,"(2) A claim presented in a second or successive habeas corpus application under section 2254 that was not presented in a prior application shall be dismissed unless—"],[1,"(A) the applicant shows that the claim relies on a new rule of constitutional law, made retroactive to cases on collateral review by the Supreme Court, that was previously unavailable; or"],[1,"(B)(i) the factual predicate for the claim could not have been discovered previously through the exercise of due diligence; and"],[1,"(ii) the facts underlying the claim, if proven and viewed in light of the evidence as a whole, would be sufficient to establish by clear and convincing evidence that, but for constitutional error, no reasonable factfinder would have found the applicant guilty of the underlying offense."],[0,"(3)(A) Before a second or successive application permitted by this section is filed in the district court, the applicant shall move in the appropriate court of appeals for an order authorizing the district court to consider the application."],[0,"(B) A motion in the court of appeals for an order authorizing the district court to consider a second or successive application shall be determined by a three-judge panel of the court of appeals."],[0,"(C) The court of appeals may authorize the filing of a second or successive application only if it determines that the application makes a prima facie showing that the application satisfies the requirements of this subsection."],[0,"(D) The court of appeals shall grant or deny the authorization to file a second or successive application not later than 30 days after the filing of the motion."],[0,"(E) The grant or denial of an authorization by a court of appeals to file a second or successive application shall not be appealable and shall not be the subject of a petition for rehearing or for a writ of certiorari."],[0,"(4) A district court shall dismiss any claim presented in a second or successive application that the court of appeals has authorized to be filed unless the applicant shows that the claim satisfies the requirements of this section."],[0,"(c) In a habeas corpus proceeding brought in behalf of a person in custody pursuant to the judgment of a State court, a prior judgment of the Supreme Court of the United States on an appeal or review by a writ of certiorari at the instance of the prisoner of the decision of such State court, shall be conclusive as to all issues of fact or law with respect to an asserted denial of a Federal right which constitutes ground for discharge in a habeas corpus proceeding, actually adjudicated by the Supreme Court therein, unless the applicant for the writ of habeas corpus shall plead and the court shall find the existence of a material and controlling fact which did not appear in the record of the proceeding in the Supreme Court and the court shall further find that the applicant for the writ of habeas corpus could not have caused such fact to appear in such record by the exercise of reasonable diligence."],[0,"(d)(1) A 1-year period of limitation shall apply to an application for a writ of habeas corpus by a person in custody pursuant to the judgment of a State court. The limitation period shall run from the latest of—"],[1,"(A) the date on which the judgment became final by the conclusion of direct review or the expiration of the time for seeking such review;"],[1,"(B) the date on which the impediment to filing an application created by State action in violation of the Constitution or laws of the United States is removed, if the applicant was prevented from filing by such State action;"],[1,"(C) the date on which the constitutional right asserted was initially recognized by the Supreme Court, if the right has been newly recognized by the Supreme Court and made retroactively applicable to cases on collateral review; or"],[1,"(D) the date on which the factual predicate of the claim or claims presented could have been discovered through the exercise of due diligence."],[0,"(2) The time during which a properly filed application for State post-conviction or other collateral review with respect to the pertinent judgment or claim is pending shall not be counted toward any period of limitation under this subsection."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2244?type=usc&year=mostrecent&link-type=html"},"by":{"1":"9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9"},"q":[{"src":"brief","b":1,"text":"the applicant shall move in the appropriate court of appeals for an order authorizing the district court to consider the application.","cite":"28 U.S.C. 2244(b)(3)(A)"},{"src":"brief","b":1,"text":"shall be determined by a three-judge panel of the court of appeals.","cite":"28 U.S.C. 2244(b)(3)(B)"},{"src":"opinion","who":"Justice Jackson, concurring","text":"present[ed] no new ground not heretofore presented and determined","cite":"28 U. S. C. § 2244(a)"},{"src":"argument","who":"Justice Sotomayor","text":"All it says is that successive habeas motions filed by federal prisoners \"must be certified, as provided in Section 2244, by a panel of the appropriate court of appeals,\" right?"},{"src":"argument","who":"Mr. Yang","text":"And, third, the application must be certified as provided in Section 2244, which means the certification process proceeds in the same manner as in 2244. (B)(3) and (b)(4) are the only provisions in Section 2244 that address the certification process for authorizing the filing of a successive application."},{"src":"argument","who":"Mr. Yang","text":"-- \"process\" doesn't appear, but it says \"certified as provided in Section 2244.\""}]},{"t":"usc","label":"28 U.S.C. § 2254","url":"https://www.law.cornell.edu/uscode/text/28/2254","subs":["(a)","(b)(1)","(b)(2)","(b)(3)","(c)"],"stext":{"head":"§2254. State custody; remedies in Federal courts","paras":[[0,"(a) The Supreme Court, a Justice thereof, a circuit judge, or a district court shall entertain an application for a writ of habeas corpus in behalf of a person in custody pursuant to the judgment of a State court only on the ground that he is in custody in violation of the Constitution or laws or treaties of the United States."],[0,"(b)(1) An application for a writ of habeas corpus on behalf of a person in custody pursuant to the judgment of a State court shall not be granted unless it appears that—"],[1,"(A) the applicant has exhausted the remedies available in the courts of the State; or"],[1,"(B)(i) there is an absence of available State corrective process; or"],[1,"(ii) circumstances exist that render such process ineffective to protect the rights of the applicant."],[0,"(2) An application for a writ of habeas corpus may be denied on the merits, notwithstanding the failure of the applicant to exhaust the remedies available in the courts of the State."],[0,"(3) A State shall not be deemed to have waived the exhaustion requirement or be estopped from reliance upon the requirement unless the State, through counsel, expressly waives the requirement."],[0,"(c) An applicant shall not be deemed to have exhausted the remedies available in the courts of the State, within the meaning of this section, if he has the right under the law of the State to raise, by any available procedure, the question presented."],[0,"(d) An application for a writ of habeas corpus on behalf of a person in custody pursuant to the judgment of a State court shall not be granted with respect to any claim that was adjudicated on the merits in State court proceedings unless the adjudication of the claim—"],[1,"(1) resulted in a decision that was contrary to, or involved an unreasonable application of, clearly established Federal law, as determined by the Supreme Court of the United States; or"],[1,"(2) resulted in a decision that was based on an unreasonable determination of the facts in light of the evidence presented in the State court proceeding."],[0,"(e)(1) In a proceeding instituted by an application for a writ of habeas corpus by a person in custody pursuant to the judgment of a State court, a determination of a factual issue made by a State court shall be presumed to be correct. The applicant shall have the burden of rebutting the presumption of correctness by clear and convincing evidence."],[0,"(2) If the applicant has failed to develop the factual basis of a claim in State court proceedings, the court shall not hold an evidentiary hearing on the claim unless the applicant shows that—"],[1,"(A) the claim relies on—"],[2,"(i) a new rule of constitutional law, made retroactive to cases on collateral review by the Supreme Court, that was previously unavailable; or"],[2,"(ii) a factual predicate that could not have been previously discovered through the exercise of due diligence; and"],[1,"(B) the facts underlying the claim would be sufficient to establish by clear and convincing evidence that but for constitutional error, no reasonable factfinder would have found the applicant guilty of the underlying offense."],[0,"(f) If the applicant challenges the sufficiency of the evidence adduced in such State court proceeding to support the State court's determination of a factual issue made therein, the applicant, if able, shall produce that part of the record pertinent to a determination of the sufficiency of the evidence to support such determination. If the applicant, because of indigency or other reason is unable to produce such part of the record, then the State shall produce such part of the record and the Federal court shall direct the State to do so by order directed to an appropriate State official. If the State cannot provide such pertinent part of the record, then the court shall determine under the existing facts and circumstances what weight shall be given to the State court's factual determination."],[0,"(g) A copy of the official records of the State court, duly certified by the clerk of such court to be a true and correct copy of a finding, judicial opinion, or other reliable written indicia showing such a factual determination by the State court shall be admissible in the Federal court proceeding."],[0,"(h) Except as provided in section 408 of the Controlled Substances Act, in all proceedings brought under this section, and any subsequent proceedings on review, the court may appoint counsel for an applicant who is or becomes financially unable to afford counsel, except as provided by a rule promulgated by the Supreme Court pursuant to statutory authority. Appointment of counsel under this section shall be governed by section 3006A of title 18."],[0,"(i) The ineffectiveness or incompetence of counsel during Federal or State collateral post-conviction proceedings shall not be a ground for relief in a proceeding arising under section 2254."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2254?type=usc&year=mostrecent&link-type=html"},"by":{"1":"9, 9, 9, 9, 9, 9"},"q":[{"src":"brief","b":1,"text":"habeas corpus application under section 2254.","cite":"28 U.S.C. 2254(b)(1)"},{"src":"brief","b":1,"text":"a person in custody pursuant to the judgment of a State court,","cite":"28 U.S.C. 2254(a)"},{"src":"argument","who":"Mr. Adler","text":"Chief Justice, and may it please the Court: By its plain terms, 2244(b)(1) applies to habeas corpus applications under Section 2254. It therefore does not apply to motions to vacate under Section 2255."},{"src":"argument","who":"Justice Barrett","text":"2255(h) does say -- and this is just -- as I'm trying to think about this argument, this clear statement point that you have, I think, is your best one on your broader argument. 2255(h) does say, though, that a second or successive motion must be certified, as provided in Section 2254, by -- 2244 by a panel of the appropriate court of appeals."},{"src":"argument","who":"Justice Gorsuch","text":"And one of the main arguments as I understand it has been because (b)(1) and (b)(2) speak about applications under Section 2254, right?"}]},{"t":"usc","label":"28 U.S.C. § 2255","url":"https://www.law.cornell.edu/uscode/text/28/2255","subs":["(a)","(e)","(h)","(h)(1)","(h)(2)"],"stext":{"head":"§2255. Federal custody; remedies on motion attacking sentence","paras":[[0,"(a) A prisoner in custody under sentence of a court established by Act of Congress claiming the right to be released upon the ground that the sentence was imposed in violation of the Constitution or laws of the United States, or that the court was without jurisdiction to impose such sentence, or that the sentence was in excess of the maximum authorized by law, or is otherwise subject to collateral attack, may move the court which imposed the sentence to vacate, set aside or correct the sentence."],[0,"(b) Unless the motion and the files and records of the case conclusively show that the prisoner is entitled to no relief, the court shall cause notice thereof to be served upon the United States attorney, grant a prompt hearing thereon, determine the issues and make findings of fact and conclusions of law with respect thereto. If the court finds that the judgment was rendered without jurisdiction, or that the sentence imposed was not authorized by law or otherwise open to collateral attack, or that there has been such a denial or infringement of the constitutional rights of the prisoner as to render the judgment vulnerable to collateral attack, the court shall vacate and set the judgment aside and shall discharge the prisoner or resentence him or grant a new trial or correct the sentence as may appear appropriate."],[0,"(c) A court may entertain and determine such motion without requiring the production of the prisoner at the hearing."],[0,"(d) An appeal may be taken to the court of appeals from the order entered on the motion as from a final judgment on application for a writ of habeas corpus."],[0,"(e) An application for a writ of habeas corpus in behalf of a prisoner who is authorized to apply for relief by motion pursuant to this section, shall not be entertained if it appears that the applicant has failed to apply for relief, by motion, to the court which sentenced him, or that such court has denied him relief, unless it also appears that the remedy by motion is inadequate or ineffective to test the legality of his detention."],[0,"(f) A 1-year period of limitation shall apply to a motion under this section. The limitation period shall run from the latest of—"],[1,"(1) the date on which the judgment of conviction becomes final;"],[1,"(2) the date on which the impediment to making a motion created by governmental action in violation of the Constitution or laws of the United States is removed, if the movant was prevented from making a motion by such governmental action;"],[1,"(3) the date on which the right asserted was initially recognized by the Supreme Court, if that right has been newly recognized by the Supreme Court and made retroactively applicable to cases on collateral review; or"],[1,"(4) the date on which the facts supporting the claim or claims presented could have been discovered through the exercise of due diligence."],[0,"(g) Except as provided in section 408 of the Controlled Substances Act, in all proceedings brought under this section, and any subsequent proceedings on review, the court may appoint counsel, except as provided by a rule promulgated by the Supreme Court pursuant to statutory authority. Appointment of counsel under this section shall be governed by section 3006A of title 18."],[0,"(h) A second or successive motion must be certified as provided in section 2244 by a panel of the appropriate court of appeals to contain—"],[1,"(1) newly discovered evidence that, if proven and viewed in light of the evidence as a whole, would be sufficient to establish by clear and convincing evidence that no reasonable factfinder would have found the movant guilty of the offense; or"],[1,"(2) a new rule of constitutional law, made retroactive to cases on collateral review by the Supreme Court, that was previously unavailable."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2255?type=usc&year=mostrecent&link-type=html"},"by":{"1":"28, 28, 28, 28, 28, 28, 28, 28"},"q":[{"src":"brief","b":1,"text":"made retroactive to cases on collateral review by","cite":"28 U.S.C. 2255(h)(2)"},{"src":"brief","b":1,"text":"must be certified as provided in section 2244 by a panel of the appropriate court of appeals","cite":"28 U.S.C. 2255(h)"},{"src":"opinion","who":"Justice Jackson, concurring","text":"shall not be required to entertain a second or successive motion for similar relief","cite":"28 U. S. C. § 2255"},{"src":"argument","who":"Mr. Adler","text":"It therefore does not apply to motions to vacate under Section 2255. After all, those motions have their own separate gatekeeping requirements."},{"src":"argument","who":"Ms. Mitchell","text":"Congress largely did away with post-conviction applications by federal prisoners, requiring them to file motions under Section 2255. And Congress amended Section 2244 to provide finality requirements for state prisoners who largely seek post-conviction relief via an application under Section 2254."}]},{"t":"rule","label":"Fed. R. App. P. 40","url":"https://www.law.cornell.edu/rules/frap/rule_40","subs":["(d)(1)"],"by":{"1":"28"}},{"t":"case","label":"Ardestani v. INS","cite":"502 U.S. 129","y":1991,"id":"1991/90-1141","sc":1,"by":{"2":"4"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"by":{"2":"12"},"q":[{"src":"brief","b":2,"text":"court of review, not first view.","cite":"544 U.S. 709, 718 n.7"}]},{"t":"case","label":"Davis v. United States","cite":"417 U.S. 333","y":1974,"id":"1973/72-1454","sc":1,"by":{"2":"14"}},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"by":{"2":"7"},"q":[{"src":"brief","b":2,"text":"a symmetrical and coherent regulatory scheme.","cite":"529 U.S. 120, 133"}]},{"t":"case","label":"Holmes Group, Inc. v. Vornado Air Circulation Sys., Inc.","cite":"535 U.S. 826","y":2002,"id":"2001/01-408","sc":1,"by":{"2":"13"}},{"t":"case","label":"Pulsifer v. United States","cite":"601 U.S. 124","y":2024,"id":"2023/22-340","sc":1,"by":{"2":"8"}},{"t":"case","label":"SAS Institute Inc. v. Iancu","cite":"584 U.S. 357","y":2018,"id":"2017/16-969","sc":1,"by":{"2":"20"}},{"t":"case","label":"Steel Co. v. Citizens for a Better Env’t","cite":"523 U.S. 83","y":1998,"id":"1997/96-643","sc":1,"by":{"2":"17"}},{"t":"case","label":"Tyler v. Cain","cite":"533 U.S. 656","y":2001,"id":"2000/00-5961","sc":1,"by":{"2":"10"}},{"t":"case","label":"United States ex rel. Schutte v. SuperValu Inc.","cite":"598 U.S. 739","y":2023,"id":"2022/21-1326","sc":1,"by":{"2":"6"}},{"t":"case","label":"United States v. Miller","cite":"145 S. Ct. 839","y":2025,"id":"2024/23-824","sc":1,"by":{"2":"6"}}]};